content.text:
{
  "name": "Xspress3 多通道 X 射线探测器",
  "name_en": "Xspress3 Multi-Channel X-ray Detector",
  "manufacturer": "Quantum Detectors",
  "description": "Xspress3 是用于同步辐射和实验室 X 射线测量的多通道探测系统/多道分析器控制设备。该驱动证据显示其支持连续采集、步进扫描、ROI 保存、数组数据采集、设定驻留时间、布防/启动/停止采集，以及文件保存和标定信息管理，适合 X 射线荧光或能谱扫描实验中的高速数据采集。",
  "description_en": "Xspress3 is a multi-channel detector and multi-channel analyzer control system for synchrotron and laboratory X-ray measurements. The driver evidence shows support for continuous acquisition, step-scan operation, ROI saving, array-data acquisition, dwell-time setting, arm/start/stop control, and file/calibration handling, making it suitable for high-speed X-ray fluorescence or spectroscopic scanning experiments.",
  "tag_hints": [
    "XRF detection",
    "multi-channel analyzer",
    "Xspress3",
    "ROI acquisition",
    "areaDetector EPICS",
    "spectroscopy scanning",
    "continuous acquisition"
  ],
  "actions": [
    {
      "action_name": "auto-ContinuousMode",
      "description": "设置为连续采集模式，用于实时读数。",
      "description_en": "Set the detector to continuous acquisition mode for live readout."
    },
    {
      "action_name": "auto-NDArrayMode",
      "description": "设置为数组数据采集模式，用于扫描时保存连续帧数组数据。",
      "description_en": "Set the detector to NDArray acquisition mode for saving streamed frame-array data during scans."
    },
    {
      "action_name": "auto-ROIMode",
      "description": "设置为 ROI 模式，用于扫描时保存感兴趣能区数据。",
      "description_en": "Set the detector to ROI mode for saving region-of-interest data during scans."
    },
    {
      "action_name": "auto-ScalerMode",
      "description": "设置为标量模式，用于步进扫描采集。",
      "description_en": "Set the detector to scaler mode for step-scan acquisition."
    },
    {
      "action_name": "auto-arm",
      "description": "布防探测器，为指定模式和帧数的采集做准备。",
      "description_en": "Arm the detector to prepare for acquisition in the selected mode and frame count."
    },
    {
      "action_name": "auto-arm_complete",
      "description": "等待并确认布防过程完成。",
      "description_en": "Wait for and confirm completion of the arming process."
    },
    {
      "action_name": "auto-config_filesaver",
      "description": "配置采集文件保存参数。",
      "description_en": "Configure file-saving parameters for detector acquisition."
    },
    {
      "action_name": "auto-connect_counters",
      "description": "连接并初始化计数器通道。",
      "description_en": "Connect and initialize detector counter channels."
    },
    {
      "action_name": "auto-disarm",
      "description": "撤防探测器，退出采集就绪状态。",
      "description_en": "Disarm the detector and leave the acquisition-ready state."
    },
    {
      "action_name": "auto-file_write_complete",
      "description": "检查或等待文件写入完成。",
      "description_en": "Check or wait for completion of file writing."
    },
    {
      "action_name": "auto-finish_capture",
      "description": "结束当前采集并完成捕获流程。",
      "description_en": "Finish the current acquisition and complete the capture process."
    },
    {
      "action_name": "auto-post_scan",
      "description": "在扫描结束后执行收尾操作并刷新计数器信息。",
      "description_en": "Run post-scan cleanup and refresh counter information after a scan."
    },
    {
      "action_name": "auto-pre_scan",
      "description": "在扫描开始前配置探测器和文件保存设置。",
      "description_en": "Configure the detector and file-saving setup before a scan starts."
    },
    {
      "action_name": "auto-save_arraydata",
      "description": "保存当前采集的数组数据到文件。",
      "description_en": "Save the currently acquired array data to a file."
    },
    {
      "action_name": "auto-save_calibration",
      "description": "将探测器标定信息保存到文件。",
      "description_en": "Save detector calibration information to a file."
    },
    {
      "action_name": "auto-set_dwelltime",
      "description": "设置每帧驻留时间。",
      "description_en": "Set the dwell time per frame."
    },
    {
      "action_name": "auto-start",
      "description": "开始采集数据，可选择同时执行布防。",
      "description_en": "Start data acquisition, optionally arming the detector first."
    },
    {
      "action_name": "auto-stop",
      "description": "停止采集数据，可选择同时撤防。",
      "description_en": "Stop data acquisition, optionally disarming the detector."
    },
    {
      "action_name": "auto-set_timeseries",
      "description": "配置时间序列采集参数。",
      "description_en": "Configure time-series acquisition settings."
    },
    {
      "action_name": "auto-roi_calib_info",
      "description": "获取或整理 ROI 标定信息。",
      "description_en": "Get or prepare ROI calibration information."
    },
    {
      "action_name": "auto-restore_rois",
      "description": "恢复已保存的 ROI 设置。",
      "description_en": "Restore previously saved ROI settings."
    },
    {
      "action_name": "auto-get_next_filename",
      "description": "获取下一个输出文件名。",
      "description_en": "Get the next output filename."
    },
    {
      "action_name": "auto-get_numcaptured",
      "description": "获取已捕获的帧数。",
      "description_en": "Get the number of captured frames."
    },
    {
      "action_name": "auto-get_last_filename",
      "description": "获取最近一次输出文件名。",
      "description_en": "Get the most recent output filename."
    }
  ]
}

